#!/usr/bin/env bash
# ============================================================
# SCORESBOX · make-archives.sh — сборка доставочных архивов
# 1. scoresbox-full.git-bundle  — git bundle --all (полная история)
# 2. scoresbox-source.zip       — git archive HEAD (только файлы репо)
# 3. scoresbox-update.git-bundle — тонкий бандл поверх 30e60c2
# 4. гайды (DEPLOY/PLAYBOOK) + README + versioned-бандлы
# Всё кладётся в download/ (панель файлов чата) и public/ (превью-ссылка).
# Папка download/ в .gitignore — при сбросе песочницы стирается,
# поэтому скрипт создаёт её сам: bash scripts/make-archives.sh.
#
# ПОЛИТИКА ХРАНЕНИЯ БАНДЛОВ (v1.0.24, требование юзера от 2026-09-20):
# ВСЕ versioned-бандлы начиная с v1.0.21 хранятся НАВСЕГДА в
# download/ и public/download/ — юзер всегда может скачать любую
# прошлую поставку. Чистятся ТОЛЬКО generic-имена (onefile).
# ⛔ ЗАПРЕЩЕНО: rm по маскам scoresbox-2026-* / scoresbox-20*.
# ============================================================
set -euo pipefail
cd "$(dirname "$0")/.."

BUNDLE=download/scoresbox-full.git-bundle
ZIP=download/scoresbox-source.zip

mkdir -p download public

echo "==> Сборка git bundle (полная история)"
rm -f "$BUNDLE"
git bundle create "$BUNDLE" --all
git bundle verify "$BUNDLE" >/dev/null && echo "    bundle корректен"

echo "==> Сборка zip исходников (tracked-файлы)"
rm -f "$ZIP"
git archive --format=zip -o "$ZIP" HEAD
unzip -t "$ZIP" >/dev/null 2>&1 && echo "    zip без ошибок"

echo "==> Копии в public/ (раздача через превью-сервер)"
cp "$BUNDLE" public/scoresbox-full.git-bundle
cp "$ZIP" public/scoresbox-source.zip

echo "==> Тонкий update-бандл (только новые коммиты поверх 30e60c2)"
# 30e60c2 — коммит, которым завершалась предыдущая поставка bundle
# (то, что пользователь уже запушил в GitHub). Если у него репо есть —
# хватит маленького файла вместо 69 МБ.
UPDATE=download/scoresbox-update.git-bundle
rm -f "$UPDATE"
if git rev-parse --verify --quiet 30e60c2^{commit} >/dev/null; then
  git bundle create "$UPDATE" main ^30e60c2
  cp "$UPDATE" public/scoresbox-update.git-bundle
  echo "    update-бандл собран"
else
  echo "    (базовый коммит 30e60c2 не найден — update-бандл пропущен)"
fi

echo "==> Самодостаточный мини-бандл (один коммит, работает в ЛЮБОМ репозитории)"
# Имя файла содержит ДАТУ — чтобы пользователь сразу отличал актуальный бандл
# от скачанных ранее. Сообщение коммита внутри тоже начинается с даты:
# проверка «git log --oneline -1 FETCH_HEAD» должна показывать ту же дату.
ONEFILE=download/scoresbox-2026-10-08-feedback52.git-bundle
# Чистим ТОЛЬКО generic-имя. Versioned-бандлы (security/next35/stage2fix/
# hotfix24/…) НЕ трогаем — см. политику хранения в шапке скрипта.
rm -f download/scoresbox-onefile.git-bundle public/scoresbox-onefile.git-bundle
ROOT="$(pwd)"
SQUASH=/tmp/sb-squash
rm -rf "$SQUASH"
git clone -q . "$SQUASH"
( cd "$SQUASH" \
  && git checkout -q --orphan tmp-main \
  && { git rm -rq --cached public/download 2>/dev/null || true; } \
  && rm -rf public/download \
  && git commit -q -m "SCORESBOX 2026-10-08 feedback52: v1.0.52 — фидбек юзера 2026-10-08: (1) ДУБЛИ ФИО (баг «опять не получается создать игрока с одинаковыми Фамилией и Именем»): КОРЕНЬ — apiPost при !r.ok возвращал только текст ошибки, структурированное тело 409 ВЫБРАСЫВАЛОСЬ: панель дублей «Это другой человек — создать всё равно» (персон) и блок-диалог SmartDelete (code/dependencies) молча не работали — админ видел голую ошибку без пути решения. Фикс: error-тело пробрасывается в res.data. Гейт смягчён: 409 — ТОЛЬКО точное совпадение Ф+И+О+ДР (создание с force); тёзки (одинаковые Ф+И без полного совпадения) создаются СВОБОДНО, ответ несёт advisory-список похожих (UI — мягкий toast про «Merge профилей»). (2) ЗАМЕНЫ И СОБЫТИЯ (фидбек: «выбираю запасных — там все в списке; игрок с замены не может участвовать в событии, если это не замена»): новый чистый модуль lib/engine/match-state — computeMatchState: НА ПОЛЕ = стартовые + вышедшие заменой − ушедшие; СКАМЕЙКА = запас из протокола, ещё не выходивший; повторный выход после ухода запрещён (легаси SUB_IN/SUB_OUT читаются). ОДНА логика для UI и сервера. validateEvent теперь принимает ТИП события и применяет правила состояния матча (когда состав подан): замена — «Выходит» ТОЛЬКО запасной ещё не выходивший, «Уходит» ТОЛЬКО игрок на поле; ГОЛ/ПЕНАЛЬТИ/АВТОГОЛ/КАРТОЧКИ/VAR — ТОЛЬКО игроки НА ПОЛЕ; состав не подан — прежний fallback заявки. UI вкладки «События»: селекторы по состоянию матча (вход — скамейка, выход/автор/ассист — на поле), пустые списки объясняют причину, мгновенная проверка до отправки. (3) КАПИТАН: один на команду — «если его пометили, больше уже нельзя»: назначение второго БЛОКИРУЕТСЯ тостом «снимите прежнего (повторный клик по его К)», кнопки К других приглушены; повторный клик по капитану снимает пометку (смена = снять → назначить). API-инвариант одного капитана не менялся. (4) ЕДИНЫЙ ПРОЦЕСС СОЗДАНИЯ ИГРОКА («создать можно разными способами — процесс должен быть един»): PersonFields.tsx — ОДИН бланк персоны (ФИО/ДР/пол/позиция/фото/специализации+свои роли) в панели «Люди» И в карточке команды → «В заявку» → «Создать нового»; общий блок полей заявки (номер/роль/дата) в обоих режимах диалога; PersonDupesNotice — единый блок антидублей с force. Один API, одинаковые подписи. (5) ПЕРСОНА→РОЛИ (вопрос юзера: игрок стал тренером/директором — что править): золотой стандарт — Person (личность) + Registration (датированная роль в команде); роль DIRECTOR «Директор» добавлена в справочники заявки и карточки; АВТОСИНК: заявка или смена роли (POST/PATCH /api/admin/registrations) добавляет роль в Person.roles — «играющий тренер» копит роли, история заявок датирована, карточка одна; практика описана в ADMIN-GUIDE.md §9. (6) МОБИЛЬНЫЕ ФОРМЫ («при заполнении с телефона верстка едет»): DialogContent — max-h-[92dvh] + overflow-y-auto + overscroll-contain + p-4 на телефоне (длинные диалоги скроллятся, а не уезжают за экран); кегль 16px на input/select при <640px — убран iOS-автозум при фокусе (главная причина «разъезда»); все формы диалогов — grid-cols-1 sm:grid-cols-2 (матч/лига/стадионы/баннеры/стат-блоки/форматы/карточка персоны/создание+заявка); строки составов протокола переносятся (s21-row-wrap). ЮНИТ: match-state.test.ts +9 (старт/замены/легаси/повторный выход/fallback/карточки), тест ролей — 13 ролей + DIRECTOR; всего 131/131. СМОК на embedded PG: тёзки/409/force; замены — 9 сценариев на сид-матче (гол и ЖК запасному 409, замена 200, гол вышедшему 200, гол ушедшему 409, повторный выход 409); синк ролей: заявка DIRECTOR → карточка [PLAYER, DIRECTOR], смена роли на COACH → +COACH. ВКЛЮЧАЕТ недоставленный diskfix52 (deploy.sh: чистка старых тегов образов до пулла, диск-префлайт 3ГБ, ретрай пулла с распознаванием no-space). МИГРАЦИЙ БД НЕТ. Верификация: tsc 0; eslint чисто; check-deps 0/0; unit 131/131; production next build ОК." \
  && git branch -M main \
  && git bundle create "$ROOT/$ONEFILE" main ) >/dev/null
cp "$ONEFILE" public/scoresbox-2026-10-08-feedback52.git-bundle
git bundle verify "$ONEFILE" >/dev/null 2>&1 && echo "    onefile-бандл корректен: $ONEFILE"

echo "==> Гайды для чтения без git (только выжившие — дублей больше нет)"
cp DEPLOY.md README.md DEPLOY-PLAYBOOK.md ADMIN-GUIDE.md download/
echo "    DEPLOY.md, README.md, DEPLOY-PLAYBOOK.md, ADMIN-GUIDE.md -> download/"

# образцовый CSV импорта (UTF-8+BOM, «;», CRLF) — генерится из скрипта
if command -v python3 >/dev/null; then python3 scripts/make-sample-import.py; fi

echo "==> public/download/ — переживает сбросы песочницы (лежит в git)"
# Бандлы в корне public/ и папка download/ исключены из git и стираются
# при пересоздании песочницы — отсюда «404» на старых ссылках.
# Копия в public/download/ коммитится в git: сброс песочницы → git restore
# → ссылка /download/... снова работает без пересборки.
# ВАЖНО: из сквош-клона выше public/download удалён — иначе бандл
# вкладывался бы сам в себя при каждой пересборке.
# ⛔ ЧИСТКИ НЕТ: versioned-бандлы v1.0.21+ копируются в download/ как есть
# (требование юзера 2026-09-20: ссылки на прошлые бандлы живут вечно).
mkdir -p public/download
cp "$ONEFILE" public/download/

# README генерируется ЗДЕСЬ (до копирования — папка download/ могла быть
# стёрта сбросом песочницы, chicken-egg).
cat > download/README.md <<'EOF'
# Поставка SCORESBOX — v1.0.52 «feedback52» (08.10.2026)

**Что это:** шесть правок от владельца (08.10): дубли ФИО игроков,
мобильная вёрстка форм, один капитан на команду, единый процесс
создания игрока, модель «игрок стал тренером/директором», замены
(запасные не участвуют в событиях, пока не вышли). Код приложения
менялся; **миграций БД нет**. В бандл также вошёл недоставленный
diskfix52 (deploy.sh — чистка образов + диск-префлайт).

## 1. «Не получается создать игрока с одинаковыми ФИО» — два слоя

- **Корень бага:** `apiPost` при ошибке выбрасывал тело ответа —
  панель «Это другой человек — создать всё равно» (и умные блок-диалоги
  удаления) молча не работали. Теперь тело 409 доезжает до UI.
- **Гейт смягчён:** совпадение только Фамилии+Имени — создание проходит
  СРАЗУ (тёзки — норма), в ответе advisory-подсказка «уже есть такой
  ФИО — если дубль, используйте Merge». 409 остаётся только при
  точном совпадении **Ф+И+Отчество+даты рождения** — с кнопкой
  «всё равно создать» (которая теперь реально появляется).

## 2. Замены и события (правила состояния матча)

Новый модуль `lib/engine/match-state` — одна логика для UI и API:
«на поле» = старт + вышедшие − ушедшие; «скамейка» = запас из
протокола, ещё не выходивший.

| Событие | Кто доступен |
|---|---|
| Замена, «▲ Выходит» | **только запасные**, ещё не выходившие |
| Замена, «▼ Уходит» | **только игроки на поле** |
| Гол / пенальти / автогол / карточки / VAR | **только игроки на поле** |

Запасной, не вышедший на поле, НЕ участвует ни в одном событии.
Повторный выход (вышел → ушёл → снова вышел) запрещён. Пустые
списки в форме объясняют причину. Действует и в UI, и через API.

## 3. Капитан — один на команду

Если капитан уже назначен, отметка другого **блокируется** с
подсказкой «сначала снимите прежнего (повторный клик по его «К»)».
Смена капитана — два явных клика: снять, назначить.

## 4. Единый процесс создания игрока

Панель «Люди» → «Персона» и карточка команды → «В заявку» →
«Создать нового» теперь открывают **один и тот же бланк**
(ФИО, дата рождения, позиция, специализации). Из карточки команды
после создания бланк сразу оформляет заявку (номер/роль/дата —
одинаковые поля в обоих режимах).

## 5. Игрок стал тренером / директором — что править

Ничего «не превращается»: карточка человека одна на всю жизнь,
роли **добавляются** заявками (датированная история). Заявка с ролью
«Тренер» / «Директор» / «Тренер вратарей» автоматически добавит роль
и на карточку — получится «играющий тренер». Добавлена роль
«Директор». Подробно — ADMIN-GUIDE.md §9.

## 6. Мобильные формы («верстка едет»)

- поля ввода на телефоне — 16px (убран iOS-автозум при фокусе);
- диалоги скроллятся (max-h 92% экрана), не уезжают за экран;
- все формы в один столбец на телефоне, в два — от планшета;
- строки составов переносятся, а не обрезаются.

## 7. Проверено

- `tsc` — 0; `eslint` — чисто; `check-deps` — 0/0;
- unit **131/131** (+9 новых: состояние матча);
- смок на локальной БД: тёзки/409/force, 9 сценариев замен,
  синхронизация ролей; production-сборка — ОК.

## 8. Применить и задеплоить (PowerShell, папка вашего клона)

```bash
git fetch "$HOME\Downloads\scoresbox-2026-10-08-feedback52.git-bundle" main
git log --oneline -1 FETCH_HEAD   # «SCORESBOX 2026-10-08 feedback52: …»
git reset --hard FETCH_HEAD && git push --force origin main
git tag v1.0.52 && git push origin v1.0.52
```

⚠️ Перед `reset --hard` гляньте `git log --oneline -3 FETCH_HEAD`:
бандл собран от вашего прод-коммита 8dec5e1 (feedback46) + diskfix52;
если в вашем main есть коммиты v1.0.47–v1.0.50, которых нет в
проде — сначала сравните (`git diff FETCH_HEAD --stat`).

После: health → "version":"1.0.52". **Миграций нет.** В этом деплое
впервые заработает diskfix52: в логе деплоя появятся строки чистки
образов и диск-префлайта — это ожидаемо.

Проверка на проде: (1) создайте двух «Иванов Иван» без даты рождения —
оба создадутся; (2) такого же с датой рождения дважды — появится
предупреждение с кнопкой; (3) протокол → «Замена»: «Выходит» — только
запас, «Уходит» — только поле; гол запасному не записывается;
(4) два «К» не поставить; (5) «В заявку» → «Создать нового» — тот же
бланк, что в «Людях»; (6) откройте админку с телефона — поля в один
столбец, ввод без «разъезда».

**Важно:** бандл содержит ветку `main` — при клоне с нуля делайте
`git clone -b main <bundle>` (без `-b` чекаут будет пустым).

